<script setup>import {ref} from 'vue';import {useRouter} from 'vue-router';import {readStore,writeStore} from '../data/storage.js';const router=useRouter();const kind=ref('Лікування');const title=ref('');const city=ref('');const details=ref('');const contact=ref('');const email=ref('');const error=ref('');function submit(){if(title.value.trim().length<8||!city.value.trim()||details.value.trim().length<20||!contact.value.trim()||!email.value.trim()){error.value='Заповніть усі поля; назва — від 8 символів, опис — від 20.';return}const items=readStore('requests',[]);items.unshift({id:'local-'+Date.now(),kind:kind.value,title:title.value.trim(),city:city.value.trim(),details:details.value.trim(),status:'pending',contact:'Локально збережена заявка; реальна перевірка не проводилася.'});writeStore('requests',items);router.push('/requests')}</script><template><div class="page-intro"><h1>Подати звернення</h1><p>Заповніть коротку форму для створення звернення на донорство або підтримку лікування.</p></div><div class="form-layout"><form class="surface request-form" @submit.prevent="submit"><label class="field-label">Тип звернення<select v-model="kind"><option>Лікування</option><option>Кров</option><option>Кістковий мозок</option></select></label><label class="field-label">Назва запиту<input v-model="title" required maxlength="80" placeholder="Коротка назва запиту"/></label><label class="field-label">Місто або регіон<input v-model="city" required maxlength="50" placeholder="Наприклад, Харків"/></label><label class="field-label">Короткий опис<textarea v-model="details" required maxlength="900" rows="3" placeholder="Суть потреби та очікувана допомога (без чутливих даних)"/></label><label class="field-label">Контактна особа<input v-model="contact" required maxlength="80" placeholder="Ім’я та прізвище"/></label><label class="field-label">Телефон або email<input v-model="email" required maxlength="100" placeholder="Наприклад, +38 (050) 123-45-67 або email@example.com"/></label><p v-if="error" role="alert" class="form-error">{{error}}</p><button type="submit" class="btn-primary submit-btn">Надіслати звернення</button></form><aside class="surface policy-panel"><h2>Цільове фінансування</h2><ol><li>Перевірка документів партнерським фондом</li><li>Погодження витрат на лікування</li><li>Оплата рахунків закладу або постачальника</li><li>Звітність без надмірних персональних даних</li></ol></aside></div></template>